"""Juji podcast episodes — Kurmancî A1–A2 pilot (original scripts). Writes /home/claude/kew_pod/kmr.json"""
import json

E = []
def ep(n, lvl, title, name, sub, lines, words, quiz):
    E.append({"id": f"kmr-{lvl.lower()}-{n:02d}", "course": "kmr", "lvl": lvl, "n": n, "title": title, "name": name, "sub": sub,
              "audio": None, "lines": [{"s": s, "t": t, "m": m} for s, t, m in lines], "words": words, "quiz": quiz})

ep(1, "A1", "Silav, ez Juji me!", "Merhaba, ben Juji!|Hi, I am Juji!|Hallo, ich bin Juji!", "Selamlaşma ve tanışma|Greetings and introductions|Begrüßung und Vorstellung",
 [("Juji", "Silav hevalno! Ez Juji me. Ev podkasta me ye.", "Merhaba arkadaşlar! Ben Juji. Bu bizim podcastimiz.|Hi friends! I am Juji. This is our podcast.|Hallo Freunde! Ich bin Juji. Das ist unser Podcast."),
  ("Juji", "Îro mêvanê me Rojda ye. Silav Rojda!", "Bugün konuğumuz Rojda. Merhaba Rojda!|Today our guest is Rojda. Hi Rojda!|Heute ist Rojda unser Gast. Hallo Rojda!"),
  ("Rojda", "Silav Juji! Tu çawa yî?", "Merhaba Juji! Nasılsın?|Hi Juji! How are you?|Hallo Juji! Wie geht es dir?"),
  ("Juji", "Ez baş im, spas. Tu çawa yî?", "İyiyim, teşekkürler. Sen nasılsın?|I am fine, thanks. How are you?|Mir geht es gut, danke. Und dir?"),
  ("Rojda", "Ez jî baş im. Ez ji Amedê me.", "Ben de iyiyim. Ben Amedliyim.|I am fine too. I am from Amed.|Mir geht es auch gut. Ich komme aus Amed."),
  ("Juji", "Tu xwendekar î?", "Öğrenci misin?|Are you a student?|Bist du Studentin?"),
  ("Rojda", "Erê, ez xwendekar im. Ez li zanîngehê dixwînim.", "Evet, öğrenciyim. Üniversitede okuyorum.|Yes, I am a student. I study at the university.|Ja, ich bin Studentin. Ich studiere an der Universität."),
  ("Juji", "Tu kîjan zimanan dizanî?", "Hangi dilleri biliyorsun?|Which languages do you know?|Welche Sprachen kannst du?"),
  ("Rojda", "Ez bi kurdî, tirkî û hinekî îngilîzî dizanim.", "Kürtçe, Türkçe ve biraz İngilizce biliyorum.|I know Kurdish, Turkish and a little English.|Ich kann Kurdisch, Türkisch und ein bisschen Englisch."),
  ("Juji", "Pir baş! Spas ji bo hatina te, Rojda.", "Çok güzel! Geldiğin için teşekkürler, Rojda.|Very good! Thanks for coming, Rojda.|Sehr gut! Danke, dass du gekommen bist, Rojda."),
  ("Rojda", "Ez spas dikim. Bi xatirê te!", "Ben teşekkür ederim. Hoşça kal!|Thank you. Goodbye!|Ich danke dir. Tschüss!"),
  ("Juji", "Oxir be! Heta podkasta din, xatirê we.", "Güle güle! Bir sonraki podcaste kadar hoşça kalın.|Goodbye! Until the next podcast, take care.|Auf Wiedersehen! Bis zum nächsten Podcast.")],
 [["mêvan", "misafir|guest|Gast"], ["zanîngeh", "üniversite|university|Universität"], ["ziman", "dil|language|Sprache"], ["hinekî", "biraz|a little|ein bisschen"], ["podkast", "podcast|podcast|Podcast"]],
 [{"q": "Rojda nereli?|Where is Rojda from?|Woher kommt Rojda?", "o": ["Amed|Amed|Amed", "Wan|Wan|Wan", "Mêrdîn|Mêrdîn|Mêrdîn"], "a": 0},
  {"q": "Rojda ne yapıyor?|What does Rojda do?|Was macht Rojda?", "o": ["Üniversitede okuyor|She studies at university|Sie studiert", "Öğretmen|She is a teacher|Sie ist Lehrerin", "Doktor|She is a doctor|Sie ist Ärztin"], "a": 0},
  {"q": "Rojda hangi dilleri biliyor?|Which languages does Rojda know?|Welche Sprachen kann Rojda?", "o": ["Kürtçe, Türkçe, biraz İngilizce|Kurdish, Turkish, a little English|Kurdisch, Türkisch, etwas Englisch", "Sadece Kürtçe|Only Kurdish|Nur Kurdisch", "Almanca ve Kürtçe|German and Kurdish|Deutsch und Kurdisch"], "a": 0}])

ep(2, "A1", "Malbata Azad", "Azad'ın ailesi|Azad's family|Azads Familie", "Aile ve ev|Family and home|Familie und Zuhause",
 [("Juji", "Silav! Îro Azad bi me re ye. Azad, malbata te çend kes e?", "Merhaba! Bugün Azad bizimle. Azad, ailen kaç kişi?|Hi! Today Azad is with us. Azad, how many people are in your family?|Hallo! Heute ist Azad bei uns. Azad, wie groß ist deine Familie?"),
  ("Azad", "Malbata min pênc kes e.", "Ailem beş kişi.|My family has five people.|Meine Familie hat fünf Personen."),
  ("Azad", "Dayika min, bavê min, xwişka min, birayê min û ez.", "Annem, babam, kız kardeşim, erkek kardeşim ve ben.|My mother, my father, my sister, my brother and me.|Meine Mutter, mein Vater, meine Schwester, mein Bruder und ich."),
  ("Juji", "Navê xwişka te çi ye?", "Kız kardeşinin adı ne?|What is your sister's name?|Wie heißt deine Schwester?"),
  ("Azad", "Navê wê Berfîn e. Ew deh salî ye.", "Onun adı Berfîn. On yaşında.|Her name is Berfîn. She is ten years old.|Sie heißt Berfîn. Sie ist zehn Jahre alt."),
  ("Juji", "Birayê te mezin e an biçûk e?", "Erkek kardeşin büyük mü küçük mü?|Is your brother older or younger?|Ist dein Bruder älter oder jünger?"),
  ("Azad", "Birayê min mezin e. Ew li Hewlêrê dixebite.", "Ağabeyim büyük. Hewlêrde çalışıyor.|My brother is older. He works in Hewlêr.|Mein Bruder ist älter. Er arbeitet in Hewlêr."),
  ("Juji", "Hûn li ku dijîn?", "Siz nerede yaşıyorsunuz?|Where do you live?|Wo wohnt ihr?"),
  ("Azad", "Em li Wanê dijîn. Mala me ne mezin e, lê pir xweş e.", "Wanda yaşıyoruz. Evimiz büyük değil ama çok güzel.|We live in Wan. Our house is not big, but it is very nice.|Wir wohnen in Wan. Unser Haus ist nicht groß, aber sehr schön."),
  ("Juji", "Kalikê te jî bi we re dijî?", "Deden de sizinle mi yaşıyor?|Does your grandfather live with you too?|Wohnt dein Opa auch bei euch?"),
  ("Azad", "Na, kalikê min li gund dijî. Em havînan diçin cem wî.", "Hayır, dedem köyde yaşıyor. Yazları onun yanına gidiyoruz.|No, my grandfather lives in the village. We visit him in summer.|Nein, mein Opa wohnt im Dorf. Im Sommer besuchen wir ihn."),
  ("Juji", "Malbateke xweş! Spas Azad.", "Güzel bir aile! Teşekkürler Azad.|A lovely family! Thanks, Azad.|Eine schöne Familie! Danke, Azad.")],
 [["malbat", "aile|family|Familie"], ["mezin", "büyük|big, older|groß, älter"], ["biçûk", "küçük|small, younger|klein, jünger"], ["kalik", "dede|grandfather|Opa"], ["cem", "yanı|at someone's place|bei"]],
 [{"q": "Azadın ailesi kaç kişi?|How many people are in Azad's family?|Wie viele Personen hat Azads Familie?", "o": ["Beş|Five|Fünf", "Dört|Four|Vier", "Altı|Six|Sechs"], "a": 0},
  {"q": "Azadın ağabeyi nerede çalışıyor?|Where does Azad's brother work?|Wo arbeitet Azads Bruder?", "o": ["Hewlêrde|In Hewlêr|In Hewlêr", "Wanda|In Wan|In Wan", "Köyde|In the village|Im Dorf"], "a": 0},
  {"q": "Yazları nereye gidiyorlar?|Where do they go in summer?|Wohin fahren sie im Sommer?", "o": ["Dedelerinin köyüne|To grandfather's village|Ins Dorf des Opas", "Denize|To the sea|Ans Meer", "Hewlêre|To Hewlêr|Nach Hewlêr"], "a": 0}])

ep(3, "A1", "Li sûkê", "Çarşıda|At the market|Auf dem Markt", "Alışveriş ve sayılar|Shopping and numbers|Einkaufen und Zahlen",
 [("Juji", "Îro em li sûka Amedê ne. Dengê sûkê tê!", "Bugün Amed çarşısındayız. Çarşının sesi geliyor!|Today we are at the Amed market. You can hear the market!|Heute sind wir auf dem Markt in Amed. Man hört den Markt!"),
  ("Firoşkar", "Fêkiyên teze! Sêv, tirî, hinar!", "Taze meyveler! Elma, üzüm, nar!|Fresh fruit! Apples, grapes, pomegranates!|Frisches Obst! Äpfel, Trauben, Granatäpfel!"),
  ("Rojda", "Silav. Kîloyek sêv bi çiqas e?", "Merhaba. Bir kilo elma ne kadar?|Hello. How much is a kilo of apples?|Hallo. Was kostet ein Kilo Äpfel?"),
  ("Firoşkar", "Kîloyek bi sî lîre ye.", "Bir kilosu otuz lira.|One kilo is thirty lira.|Ein Kilo kostet dreißig Lira."),
  ("Rojda", "Ez du kîlo sêv dixwazim. Hinar jî heye?", "İki kilo elma istiyorum. Nar da var mı?|I want two kilos of apples. Are there pomegranates too?|Ich möchte zwei Kilo Äpfel. Gibt es auch Granatäpfel?"),
  ("Firoşkar", "Belê, hinarên me pir şîrîn in. Kîloyek bi çil lîre ye.", "Evet, narlarımız çok tatlı. Bir kilosu kırk lira.|Yes, our pomegranates are very sweet. A kilo is forty lira.|Ja, unsere Granatäpfel sind sehr süß. Ein Kilo kostet vierzig Lira."),
  ("Rojda", "Baş e, kîloyek hinar jî bide min.", "Tamam, bir kilo nar da ver.|OK, give me a kilo of pomegranates too.|Gut, gib mir auch ein Kilo Granatäpfel."),
  ("Firoşkar", "Hemû bi hev re sed lîre ye.", "Hepsi birlikte yüz lira.|All together it is a hundred lira.|Alles zusammen kostet hundert Lira."),
  ("Rojda", "Fermo, sed lîre. Spas!", "Buyur, yüz lira. Teşekkürler!|Here you are, a hundred lira. Thanks!|Bitte, hundert Lira. Danke!"),
  ("Firoşkar", "Noşî can be! Dîsa werin.", "Afiyet olsun! Yine gelin.|Enjoy! Come again.|Guten Appetit! Kommt wieder."),
  ("Juji", "Gotinên vê podkastê: bi çiqas e, kîlo, teze, şîrîn. Hûn dikarin li sûkê bi kar bînin!", "Bu bölümün sözleri: ne kadar, kilo, taze, tatlı. Çarşıda kullanabilirsiniz!|Words of this episode: how much, kilo, fresh, sweet. Use them at the market!|Wörter dieser Folge: wie viel, Kilo, frisch, süß. Benutzt sie auf dem Markt!")],
 [["sûk", "çarşı|market|Markt"], ["teze", "taze|fresh|frisch"], ["bi çiqas e?", "ne kadar?|how much is it?|wie viel kostet es?"], ["hinar", "nar|pomegranate|Granatapfel"], ["şîrîn", "tatlı|sweet|süß"]],
 [{"q": "Bir kilo elma kaç lira?|How much is a kilo of apples?|Was kostet ein Kilo Äpfel?", "o": ["Otuz|Thirty|Dreißig", "Kırk|Forty|Vierzig", "Yüz|A hundred|Hundert"], "a": 0},
  {"q": "Rojda ne alıyor?|What does Rojda buy?|Was kauft Rojda?", "o": ["İki kilo elma, bir kilo nar|Two kilos of apples, one of pomegranates|Zwei Kilo Äpfel, ein Kilo Granatäpfel", "Üzüm ve elma|Grapes and apples|Trauben und Äpfel", "Sadece nar|Only pomegranates|Nur Granatäpfel"], "a": 0},
  {"q": "Hepsi ne kadar tutuyor?|What is the total?|Wie viel kostet alles?", "o": ["Yüz lira|A hundred lira|Hundert Lira", "Yetmiş lira|Seventy lira|Siebzig Lira", "Elli lira|Fifty lira|Fünfzig Lira"], "a": 0}])

ep(4, "A1", "Taştê", "Kahvaltı|Breakfast|Frühstück", "Yemek ve içecek|Food and drink|Essen und Trinken",
 [("Juji", "Sibe baş! Ez birçî me. Dema taştê ye!", "Günaydın! Acıktım. Kahvaltı zamanı!|Good morning! I am hungry. It is breakfast time!|Guten Morgen! Ich habe Hunger. Zeit fürs Frühstück!"),
  ("Dayik", "Juji, were! Taştê amade ye.", "Juji, gel! Kahvaltı hazır.|Juji, come! Breakfast is ready.|Juji, komm! Das Frühstück ist fertig."),
  ("Juji", "Li ser sifrê çi heye?", "Sofrada ne var?|What is on the table?|Was ist auf dem Tisch?"),
  ("Dayik", "Nanê tenûrê, penîr, hêk, zeytûn û hingiv.", "Tandır ekmeği, peynir, yumurta, zeytin ve bal.|Tandoor bread, cheese, eggs, olives and honey.|Tandoor-Brot, Käse, Eier, Oliven und Honig."),
  ("Juji", "Ax, hingiv! Ez ji hingiv pir hez dikim.", "Ah, bal! Balı çok severim.|Oh, honey! I love honey.|Oh, Honig! Ich liebe Honig."),
  ("Dayik", "Tu çay dixwazî an şîr?", "Çay mı istersin süt mü?|Do you want tea or milk?|Möchtest du Tee oder Milch?"),
  ("Juji", "Çay, ji kerema xwe. Bi şekir.", "Çay lütfen. Şekerli.|Tea, please. With sugar.|Tee, bitte. Mit Zucker."),
  ("Dayik", "Fermo. Nan hîn germ e.", "Buyur. Ekmek hâlâ sıcak.|Here you are. The bread is still warm.|Bitte. Das Brot ist noch warm."),
  ("Juji", "Destê te sax be, dayê. Pir xweş e!", "Eline sağlık, anne. Çok güzel!|Bless your hands, mum. It is delicious!|Danke, Mama. Es ist köstlich!"),
  ("Dayik", "Noşî can be, kurê min.", "Afiyet olsun, oğlum.|Enjoy, my son.|Guten Appetit, mein Sohn."),
  ("Juji", "Hûn jî bibêjin: destê te sax be! Ev gotin piştî xwarinê tê gotin.", "Siz de söyleyin: eline sağlık! Bu söz yemekten sonra söylenir.|You say it too: destê te sax be! It is said after a meal.|Sagt es auch: destê te sax be! Man sagt es nach dem Essen.")],
 [["taştê", "kahvaltı|breakfast|Frühstück"], ["birçî", "aç|hungry|hungrig"], ["hingiv", "bal|honey|Honig"], ["amade", "hazır|ready|fertig"], ["destê te sax be", "eline sağlık|thanks for the meal|danke fürs Essen"]],
 [{"q": "Juji ne içiyor?|What does Juji drink?|Was trinkt Juji?", "o": ["Şekerli çay|Tea with sugar|Tee mit Zucker", "Süt|Milk|Milch", "Su|Water|Wasser"], "a": 0},
  {"q": "Juji neyi çok seviyor?|What does Juji love?|Was liebt Juji?", "o": ["Balı|Honey|Honig", "Peyniri|Cheese|Käse", "Zeytini|Olives|Oliven"], "a": 0},
  {"q": "«Destê te sax be» ne zaman söylenir?|When do you say «destê te sax be»?|Wann sagt man «destê te sax be»?", "o": ["Yemekten sonra|After a meal|Nach dem Essen", "Sabah uyanınca|When waking up|Beim Aufwachen", "Vedalaşırken|When saying goodbye|Beim Abschied"], "a": 0}])

ep(5, "A1", "Rojeke min", "Bir günüm|A day of mine|Ein Tag von mir", "Günlük rutin ve saat|Daily routine and time|Tagesablauf und Uhrzeit",
 [("Juji", "Berfîn, roja te çawa derbas dibe?", "Berfîn, günün nasıl geçiyor?|Berfîn, how does your day go?|Berfîn, wie verläuft dein Tag?"),
  ("Berfîn", "Ez saet heftan radibim.", "Saat yedide kalkarım.|I get up at seven.|Ich stehe um sieben auf."),
  ("Berfîn", "Paşê ez rû û destên xwe dişom û taştê dikim.", "Sonra yüzümü ve ellerimi yıkar, kahvaltı ederim.|Then I wash my face and hands and have breakfast.|Dann wasche ich Gesicht und Hände und frühstücke."),
  ("Juji", "Tu kengî diçî dibistanê?", "Okula ne zaman gidersin?|When do you go to school?|Wann gehst du zur Schule?"),
  ("Berfîn", "Saet heşt û nîv. Dibistan nêzîkî mala me ye, ez peyatî diçim.", "Sekiz buçukta. Okul evimize yakın, yürüyerek giderim.|At half past eight. The school is near our house, I walk.|Um halb neun. Die Schule ist nah, ich gehe zu Fuß."),
  ("Juji", "Piştî dibistanê tu çi dikî?", "Okuldan sonra ne yaparsın?|What do you do after school?|Was machst du nach der Schule?"),
  ("Berfîn", "Ez wezîfeyên xwe dikim û bi hevalên xwe re dilîzim.", "Ödevlerimi yaparım ve arkadaşlarımla oynarım.|I do my homework and play with my friends.|Ich mache Hausaufgaben und spiele mit Freunden."),
  ("Juji", "Êvaran jî?", "Akşamları da?|And in the evenings?|Und abends?"),
  ("Berfîn", "Em bi hev re şîv dixwin. Paşê ez pirtûkê dixwînim.", "Birlikte akşam yemeği yeriz. Sonra kitap okurum.|We eat dinner together. Then I read a book.|Wir essen zusammen zu Abend. Dann lese ich ein Buch."),
  ("Juji", "Tu saet çendan radizê?", "Saat kaçta yatarsın?|What time do you go to bed?|Um wie viel Uhr gehst du schlafen?"),
  ("Berfîn", "Saet dehan. Şev baş, Juji!", "Saat onda. İyi geceler, Juji!|At ten. Good night, Juji!|Um zehn. Gute Nacht, Juji!")],
 [["radibim", "kalkarım|I get up|ich stehe auf"], ["peyatî", "yürüyerek|on foot|zu Fuß"], ["wezîfe", "ödev|homework|Hausaufgabe"], ["şîv", "akşam yemeği|dinner|Abendessen"], ["radizê", "yatar, uyur|goes to bed|schläft"]],
 [{"q": "Berfîn kaçta kalkıyor?|What time does Berfîn get up?|Wann steht Berfîn auf?", "o": ["Yedide|At seven|Um sieben", "Sekizde|At eight|Um acht", "Onda|At ten|Um zehn"], "a": 0},
  {"q": "Berfîn okula nasıl gidiyor?|How does Berfîn go to school?|Wie kommt Berfîn zur Schule?", "o": ["Yürüyerek|On foot|Zu Fuß", "Otobüsle|By bus|Mit dem Bus", "Arabayla|By car|Mit dem Auto"], "a": 0},
  {"q": "Akşam yemeğinden sonra ne yapıyor?|What does she do after dinner?|Was macht sie nach dem Abendessen?", "o": ["Kitap okuyor|She reads a book|Sie liest ein Buch", "Televizyon izliyor|She watches TV|Sie sieht fern", "Oyun oynuyor|She plays games|Sie spielt"], "a": 0}])

ep(1, "A2", "Bihar û Newroz", "Bahar ve Newroz|Spring and Newroz|Frühling und Newroz", "Hava, mevsimler ve bayram|Weather, seasons and festival|Wetter, Jahreszeiten und Fest",
 [("Juji", "Bihar hat! Hewa germ dibe û çiya kesk dibin.", "Bahar geldi! Hava ısınıyor, dağlar yeşilleniyor.|Spring has come! It is getting warm and the mountains turn green.|Der Frühling ist da! Es wird warm und die Berge werden grün."),
  ("Juji", "Mêvanê me Bapîr e. Bapîr, li gund bihar çawa bû?", "Konuğumuz dede. Dede, köyde bahar nasıldı?|Our guest is Grandpa. Grandpa, what was spring like in the village?|Unser Gast ist Opa. Opa, wie war der Frühling im Dorf?"),
  ("Bapîr", "Dema ez zarok bûm, berf heta Adarê dima.", "Ben çocukken kar marta kadar kalırdı.|When I was a child, the snow stayed until March.|Als ich ein Kind war, blieb der Schnee bis März."),
  ("Bapîr", "Paşê kulîlk vedibûn û em diçûn çiyayan.", "Sonra çiçekler açardı ve dağlara giderdik.|Then the flowers opened and we went to the mountains.|Dann blühten die Blumen und wir gingen in die Berge."),
  ("Juji", "Newroz çawa derbas dibû?", "Newroz nasıl geçerdi?|How was Newroz celebrated?|Wie wurde Newroz gefeiert?"),
  ("Bapîr", "Êvara berî Newrozê me li ser banan agir vêdixist.", "Newrozdan önceki akşam damlarda ateş yakardık.|On the evening before Newroz we lit fires on the roofs.|Am Abend vor Newroz zündeten wir Feuer auf den Dächern an."),
  ("Bapîr", "Roja Newrozê hemû gund derdiketin derve, govend dikirin.", "Newroz günü bütün köy dışarı çıkar, halay çekerdi.|On Newroz day the whole village went outside and danced.|Am Newroz-Tag ging das ganze Dorf hinaus und tanzte."),
  ("Juji", "Îro jî Newroz bi heman coşê tê pîroz kirin.", "Bugün de Newroz aynı coşkuyla kutlanıyor.|Today Newroz is still celebrated with the same joy.|Auch heute wird Newroz mit derselben Freude gefeiert."),
  ("Bapîr", "Erê. Newroz cejna biharê û azadiyê ye.", "Evet. Newroz baharın ve özgürlüğün bayramıdır.|Yes. Newroz is the festival of spring and freedom.|Ja. Newroz ist das Fest des Frühlings und der Freiheit."),
  ("Juji", "Newroza we pîroz be!", "Newrozunuz kutlu olsun!|Happy Newroz!|Frohes Newroz!")],
 [["bihar", "bahar|spring|Frühling"], ["berf", "kar|snow|Schnee"], ["kulîlk", "çiçek|flower|Blume"], ["agir vêxistin", "ateş yakmak|to light a fire|Feuer anzünden"], ["govend", "halay|folk dance|Reigentanz"]],
 [{"q": "Dede çocukken kar ne zamana kadar kalırdı?|Until when did the snow stay?|Bis wann blieb der Schnee?", "o": ["Marta kadar|Until March|Bis März", "Mayısa kadar|Until May|Bis Mai", "Hiç yağmazdı|It never snowed|Es schneite nie"], "a": 0},
  {"q": "Newrozdan önceki akşam ne yaparlardı?|What did they do the evening before Newroz?|Was taten sie am Abend vor Newroz?", "o": ["Damlarda ateş yakarlardı|Lit fires on roofs|Feuer auf Dächern", "Şehre giderlerdi|Went to town|In die Stadt fahren", "Erken yatarlardı|Went to bed early|Früh schlafen"], "a": 0},
  {"q": "Dedeye göre Newroz neyin bayramı?|According to Grandpa, Newroz is the festival of…|Laut Opa ist Newroz das Fest…", "o": ["Baharın ve özgürlüğün|Spring and freedom|Frühling und Freiheit", "Hasadın|The harvest|Der Ernte", "Kışın|Winter|Des Winters"], "a": 0}])

ep(2, "A2", "Rêwîtiya Wanê", "Wan yolculuğu|A trip to Wan|Eine Reise nach Wan", "Yolculuk ve geçmiş zaman|Travel and the past tense|Reisen und Vergangenheit",
 [("Juji", "Azad, tu hefteya borî çûbû Wanê. Rêwîtî çawa bû?", "Azad, geçen hafta Wana gitmiştin. Yolculuk nasıldı?|Azad, you went to Wan last week. How was the trip?|Azad, du warst letzte Woche in Wan. Wie war die Reise?"),
  ("Azad", "Pir xweş bû! Ez bi otobusê çûm. Rê şeş saetan dom kir.", "Çok güzeldi! Otobüsle gittim. Yol altı saat sürdü.|It was great! I went by bus. The road took six hours.|Sehr schön! Ich fuhr mit dem Bus. Die Fahrt dauerte sechs Stunden."),
  ("Juji", "Te li Wanê çi dît?", "Wanda ne gördün?|What did you see in Wan?|Was hast du in Wan gesehen?"),
  ("Azad", "Min Gola Wanê dît. Av şîn bû, mîna asîmanê.", "Wan Gölünü gördüm. Su maviydi, gökyüzü gibi.|I saw Lake Wan. The water was blue, like the sky.|Ich habe den Wansee gesehen. Das Wasser war blau wie der Himmel."),
  ("Azad", "Em bi keştiyê çûn Girava Axtamarê.", "Tekneyle Ahtamar Adasına gittik.|We went to Akdamar Island by boat.|Wir fuhren mit dem Boot zur Insel Akdamar."),
  ("Juji", "Te taştêya Wanê xwar?", "Wan kahvaltısını yedin mi?|Did you eat a Wan breakfast?|Hast du ein Wan-Frühstück gegessen?"),
  ("Azad", "Belê! Min penîrê bi giya û qeymax xwar. Pir xweş bû.", "Evet! Otlu peynir ve kaymak yedim. Çok güzeldi.|Yes! I ate herb cheese and clotted cream. It was delicious.|Ja! Ich habe Kräuterkäse und Rahm gegessen. Sehr lecker."),
  ("Juji", "Tu li ku mayî?", "Nerede kaldın?|Where did you stay?|Wo hast du übernachtet?"),
  ("Azad", "Ez li mala hevalekî xwe mam. Ew ji min re bû rêber.", "Bir arkadaşımın evinde kaldım. Bana rehber oldu.|I stayed at a friend's house. He was my guide.|Ich wohnte bei einem Freund. Er war mein Führer."),
  ("Juji", "Tu dîsa diçî?", "Yine gidecek misin?|Will you go again?|Fährst du wieder hin?"),
  ("Azad", "Bê guman! Havîna bê ez dixwazim li dora golê bigerim.", "Elbette! Gelecek yaz gölün çevresini gezmek istiyorum.|Of course! Next summer I want to travel around the lake.|Natürlich! Nächsten Sommer möchte ich um den See reisen.")],
 [["hefteya borî", "geçen hafta|last week|letzte Woche"], ["gol", "göl|lake|See"], ["keştî", "tekne, gemi|boat|Boot"], ["girav", "ada|island|Insel"], ["rêber", "rehber|guide|Führer"]],
 [{"q": "Azad Wana nasıl gitti?|How did Azad travel to Wan?|Wie reiste Azad nach Wan?", "o": ["Otobüsle|By bus|Mit dem Bus", "Uçakla|By plane|Mit dem Flugzeug", "Arabayla|By car|Mit dem Auto"], "a": 0},
  {"q": "Adaya nasıl gittiler?|How did they get to the island?|Wie kamen sie zur Insel?", "o": ["Tekneyle|By boat|Mit dem Boot", "Yürüyerek|On foot|Zu Fuß", "Otobüsle|By bus|Mit dem Bus"], "a": 0},
  {"q": "Azad nerede kaldı?|Where did Azad stay?|Wo übernachtete Azad?", "o": ["Arkadaşının evinde|At a friend's house|Bei einem Freund", "Otelde|In a hotel|Im Hotel", "Çadırda|In a tent|Im Zelt"], "a": 0}])

ep(3, "A2", "Li ba bijîşk", "Doktorda|At the doctor's|Beim Arzt", "Sağlık ve vücut|Health and the body|Gesundheit und Körper",
 [("Juji", "Îro em li nexweşxaneyê ne. Rojda nexweş e.", "Bugün hastanedeyiz. Rojda hasta.|Today we are at the hospital. Rojda is ill.|Heute sind wir im Krankenhaus. Rojda ist krank."),
  ("Bijîşk", "Silav, li ku derê te diêşe?", "Merhaba, neren ağrıyor?|Hello, where does it hurt?|Hallo, wo tut es weh?"),
  ("Rojda", "Serê min diêşe û qirika min jî diêşe.", "Başım ağrıyor, boğazım da ağrıyor.|My head hurts and my throat hurts too.|Mein Kopf tut weh und mein Hals auch."),
  ("Bijîşk", "Ji kengê ve?", "Ne zamandan beri?|Since when?|Seit wann?"),
  ("Rojda", "Ji duhî ve. Min şev baş xew nekir.", "Dünden beri. Gece iyi uyuyamadım.|Since yesterday. I didn't sleep well last night.|Seit gestern. Ich habe nachts schlecht geschlafen."),
  ("Bijîşk", "Germahiya te heye. Tu sar bûyî.", "Ateşin var. Üşütmüşsün.|You have a fever. You have caught a cold.|Du hast Fieber. Du hast dich erkältet."),
  ("Bijîşk", "Rojê sê caran vî dermanî bixwe û gelek av vexwe.", "Bu ilacı günde üç kez iç ve çok su iç.|Take this medicine three times a day and drink lots of water.|Nimm dieses Medikament dreimal täglich und trink viel Wasser."),
  ("Rojda", "Ez dikarim herim kar?", "İşe gidebilir miyim?|Can I go to work?|Kann ich zur Arbeit gehen?"),
  ("Bijîşk", "Na, du rojan li malê bimîne û bêhna xwe vede.", "Hayır, iki gün evde kal ve dinlen.|No, stay at home for two days and rest.|Nein, bleib zwei Tage zu Hause und ruh dich aus."),
  ("Rojda", "Baş e, gelek spas, doktor.", "Tamam, çok teşekkürler doktor.|OK, thank you very much, doctor.|Gut, vielen Dank, Frau Doktor."),
  ("Juji", "Derbas be, Rojda! Gava kesek nexweş be, em dibêjin: derbas be.", "Geçmiş olsun, Rojda! Biri hasta olunca «derbas be» deriz.|Get well, Rojda! When someone is ill, we say «derbas be».|Gute Besserung, Rojda! Wenn jemand krank ist, sagen wir «derbas be».")],
 [["nexweşxane", "hastane|hospital|Krankenhaus"], ["diêşe", "ağrıyor|it hurts|tut weh"], ["qirik", "boğaz|throat|Hals"], ["germahî", "ateş|fever|Fieber"], ["derbas be", "geçmiş olsun|get well soon|gute Besserung"]],
 [{"q": "Rojdanın neresi ağrıyor?|What hurts Rojda?|Was tut Rojda weh?", "o": ["Başı ve boğazı|Head and throat|Kopf und Hals", "Midesi|Stomach|Bauch", "Ayağı|Foot|Fuß"], "a": 0},
  {"q": "İlacı günde kaç kez içecek?|How often should she take the medicine?|Wie oft soll sie das Medikament nehmen?", "o": ["Üç kez|Three times|Dreimal", "Bir kez|Once|Einmal", "İki kez|Twice|Zweimal"], "a": 0},
  {"q": "Doktor ne diyor?|What does the doctor say?|Was sagt die Ärztin?", "o": ["İki gün evde dinlen|Rest at home for two days|Zwei Tage ausruhen", "Hemen işe git|Go to work now|Sofort arbeiten", "Hastanede kal|Stay in hospital|Im Krankenhaus bleiben"], "a": 0}])

ep(4, "A2", "Dengbêj", "Dengbêjler|Dengbêj singers|Dengbêj-Sänger", "Kürt kültürü ve müzik|Kurdish culture and music|Kurdische Kultur und Musik",
 [("Juji", "Îro mijara me dengbêj in. Bapîr, dengbêj kî ne?", "Bugünün konusu dengbêjler. Dede, dengbêjler kimdir?|Today's topic is dengbêj. Grandpa, who are the dengbêj?|Unser Thema heute: Dengbêj. Opa, wer sind die Dengbêj?"),
  ("Bapîr", "Dengbêj stranbêj û çîrokbêj in. Ew bê amûr, tenê bi deng distrên.", "Dengbêjler hem şarkıcı hem hikâye anlatıcısıdır. Çalgısız, sadece sesle söylerler.|Dengbêj are singers and storytellers. They sing without instruments, only with their voice.|Dengbêj sind Sänger und Erzähler. Sie singen ohne Instrumente, nur mit der Stimme."),
  ("Juji", "Stranên wan li ser çi ne?", "Şarkıları ne hakkında?|What are their songs about?|Worüber singen sie?"),
  ("Bapîr", "Li ser evînê, şer, koçberiyê û jiyana gundan.", "Aşk, savaş, göç ve köy hayatı üzerine.|About love, war, migration and village life.|Über Liebe, Krieg, Auswanderung und das Dorfleben."),
  ("Bapîr", "Berê, di şevên zivistanê de, mirov li odeyan kom dibûn û guhdariya dengbêjan dikirin.", "Eskiden kış gecelerinde insanlar odalarda toplanır, dengbêjleri dinlerdi.|In the old days, on winter nights people gathered in rooms and listened to the dengbêj.|Früher versammelten sich die Leute in Winternächten und hörten den Dengbêj zu."),
  ("Juji", "Dengbêj stranan ji ku hîn dibûn?", "Dengbêjler şarkıları nereden öğrenirdi?|Where did dengbêj learn their songs?|Wo lernten die Dengbêj ihre Lieder?"),
  ("Bapîr", "Ji dengbêjên mezin. Wan stran ji ber dikirin û ji nifşekî derbasî nifşekî din dikirin.", "Büyük dengbêjlerden. Şarkıları ezberler, kuşaktan kuşağa aktarırlardı.|From the great dengbêj. They memorised the songs and passed them from generation to generation.|Von den großen Dengbêj. Sie lernten die Lieder auswendig und gaben sie weiter."),
  ("Juji", "Îro jî dengbêj hene?", "Bugün de dengbêj var mı?|Are there still dengbêj today?|Gibt es heute noch Dengbêj?"),
  ("Bapîr", "Belê. Li Amedê Mala Dengbêjan heye. Her roj dengbêj li wir distrên.", "Evet. Amedde Dengbêjler Evi var. Her gün orada dengbêjler söylüyor.|Yes. In Amed there is the House of Dengbêj. Every day dengbêj sing there.|Ja. In Amed gibt es das Haus der Dengbêj. Dort singen jeden Tag Dengbêj."),
  ("Juji", "Gava hûn biçin Amedê, serdana Mala Dengbêjan bikin!", "Amede giderseniz Dengbêjler Evini ziyaret edin!|If you go to Amed, visit the House of Dengbêj!|Wenn ihr nach Amed fahrt, besucht das Haus der Dengbêj!")],
 [["dengbêj", "dengbêj, sözlü gelenek şarkıcısı|traditional singer-storyteller|traditioneller Sänger und Erzähler"], ["stran", "şarkı|song|Lied"], ["amûr", "çalgı|instrument|Instrument"], ["koçberî", "göç|migration|Auswanderung"], ["nifş", "kuşak|generation|Generation"]],
 [{"q": "Dengbêjler nasıl söyler?|How do dengbêj sing?|Wie singen Dengbêj?", "o": ["Çalgısız, sadece sesle|Without instruments, only voice|Ohne Instrumente, nur Stimme", "Saz ile|With a saz|Mit einer Saz", "Davul zurna ile|With drum and zurna|Mit Trommel und Zurna"], "a": 0},
  {"q": "Eskiden dengbêjler ne zaman dinlenirdi?|When were dengbêj heard in the old days?|Wann hörte man früher Dengbêj?", "o": ["Kış gecelerinde|On winter nights|In Winternächten", "Yaz sabahlarında|On summer mornings|An Sommermorgen", "Sadece düğünlerde|Only at weddings|Nur bei Hochzeiten"], "a": 0},
  {"q": "Dengbêjler Evi nerede?|Where is the House of Dengbêj?|Wo ist das Haus der Dengbêj?", "o": ["Amedde|In Amed|In Amed", "Wanda|In Wan|In Wan", "Hewlêrde|In Hewlêr|In Hewlêr"], "a": 0}])

ep(5, "A2", "Plana havînê", "Yaz planı|Summer plans|Sommerpläne", "Gelecek planları|Future plans|Zukunftspläne",
 [("Juji", "Havîn nêzîk e! Berfîn, Azad, planên we çi ne?", "Yaz yaklaşıyor! Berfîn, Azad, planlarınız ne?|Summer is near! Berfîn, Azad, what are your plans?|Der Sommer kommt! Berfîn, Azad, was habt ihr vor?"),
  ("Berfîn", "Ez ê biçim gundê kalikê xwe. Ez ê li wir alîkariya wî bikim.", "Dedemin köyüne gideceğim. Orada ona yardım edeceğim.|I will go to my grandfather's village. I will help him there.|Ich fahre ins Dorf meines Opas. Ich werde ihm dort helfen."),
  ("Juji", "Tu ê çi bikî li gund?", "Köyde ne yapacaksın?|What will you do in the village?|Was wirst du im Dorf machen?"),
  ("Berfîn", "Ez ê pez biçêrînim û sêvan berhev bikim.", "Koyunları otlatacak ve elma toplayacağım.|I will graze the sheep and pick apples.|Ich werde die Schafe hüten und Äpfel pflücken."),
  ("Azad", "Ez ê kursa kurdî bixwînim. Ez dixwazim baştir binivîsim.", "Kürtçe kursuna gideceğim. Daha iyi yazmak istiyorum.|I will take a Kurdish course. I want to write better.|Ich mache einen Kurdischkurs. Ich möchte besser schreiben."),
  ("Juji", "Pir baş! Hûn ê biçin deryayê jî?", "Çok güzel! Denize de gidecek misiniz?|Great! Will you go to the sea too?|Super! Fahrt ihr auch ans Meer?"),
  ("Azad", "Belkî. Eger pereyê me hebe, em ê hefteyekê biçin.", "Belki. Paramız olursa bir hafta gideceğiz.|Maybe. If we have money, we will go for a week.|Vielleicht. Wenn wir Geld haben, fahren wir eine Woche."),
  ("Berfîn", "Lê ez ji germa havînê hez nakim. Ez çiya tercîh dikim.", "Ama ben yaz sıcağını sevmem. Dağı tercih ederim.|But I don't like the summer heat. I prefer the mountains.|Aber ich mag die Sommerhitze nicht. Ich bevorzuge die Berge."),
  ("Juji", "Ez ê jî her hefte podkasteke nû çêkim. Hûn ê guhdarî bikin?", "Ben de her hafta yeni bir podcast yapacağım. Dinleyecek misiniz?|And I will make a new podcast every week. Will you listen?|Und ich mache jede Woche einen neuen Podcast. Hört ihr zu?"),
  ("Azad", "Bê guman, Juji!", "Elbette, Juji!|Of course, Juji!|Natürlich, Juji!"),
  ("Juji", "Havîneke xweş ji we re! Bi xatirê we.", "Size güzel bir yaz! Hoşça kalın.|Have a nice summer! Goodbye.|Einen schönen Sommer! Tschüss.")],
 [["ez ê … bikim", "yapacağım|I will do|ich werde … tun"], ["pez", "koyun sürüsü|sheep, flock|Schafe, Herde"], ["berhev kirin", "toplamak|to pick, to gather|sammeln"], ["belkî", "belki|maybe|vielleicht"], ["tercîh kirin", "tercih etmek|to prefer|bevorzugen"]],
 [{"q": "Berfîn yazın nereye gidecek?|Where will Berfîn go in summer?|Wohin fährt Berfîn im Sommer?", "o": ["Dedesinin köyüne|To her grandfather's village|Ins Dorf ihres Opas", "Denize|To the sea|Ans Meer", "Hewlêre|To Hewlêr|Nach Hewlêr"], "a": 0},
  {"q": "Azad ne yapacak?|What will Azad do?|Was macht Azad?", "o": ["Kürtçe kursuna gidecek|Take a Kurdish course|Einen Kurdischkurs", "Çalışacak|Work|Arbeiten", "Yüzecek|Swim|Schwimmen"], "a": 0},
  {"q": "Berfîn neyi sevmiyor?|What doesn't Berfîn like?|Was mag Berfîn nicht?", "o": ["Yaz sıcağını|The summer heat|Die Sommerhitze", "Dağları|Mountains|Berge", "Elmaları|Apples|Äpfel"], "a": 0}])

ep(1, "B1", "Bîranînên zozanan", "Yayla anıları|Memories of the summer pastures|Erinnerungen an die Sommerweiden", "Geçmiş alışkanlıklar ve koşul cümleleri|Past habits and conditionals|Vergangene Gewohnheiten und Bedingungssätze",
 [("Juji", "Silav hevalno! Ez Juji me, û ev podkasta asta B1 ye. Îro du mêvanên me hene: Bapîr û Dapîr!", "Merhaba arkadaşlar! Ben Juji, bu da B1 seviyesi podcasti. Bugün iki konuğumuz var: Dede ve Nine!|Hi friends! I am Juji, and this is the B1 podcast. Today we have two guests: Grandpa and Grandma!|Hallo Freunde! Ich bin Juji, und das ist der B1-Podcast. Heute haben wir zwei Gäste: Opa und Oma!"),
  ("Juji", "Bapîr, dema tu ciwan bûyî, havîn li gundê we çawa derbas dibûn?", "Dede, sen gençken köyünüzde yazlar nasıl geçerdi?|Grandpa, when you were young, how did summers go in your village?|Opa, wie verliefen die Sommer in eurem Dorf, als du jung warst?"),
  ("Bapîr", "Ax, lawo... Wê demê, em her havîn bi pez û dewarên xwe re derdiketin zozanan.", "Ah, oğlum... O zamanlar her yaz koyunlarımız ve hayvanlarımızla yaylaya çıkardık.|Oh, my boy... Back then, every summer we went up to the summer pastures with our sheep and cattle.|Ach, mein Junge... Damals zogen wir jeden Sommer mit unseren Schafen und Rindern auf die Sommerweiden."),
  ("Dapîr", "Zozan, cihên bilind ên çiyayan in. Li wir hewa hênik e, giya jî pir e.", "Yayla, dağların yüksek yerleridir. Orada hava serin, ot da boldur.|Summer pastures are the high places in the mountains. The air is cool there, and there is plenty of grass.|Sommerweiden sind die hohen Orte in den Bergen. Dort ist die Luft kühl, und es gibt viel Gras."),
  ("Juji", "Hûn çiqas li wir diman?", "Orada ne kadar kalırdınız?|How long did you stay there?|Wie lange bliebt ihr dort?"),
  ("Bapîr", "Ji meha Gulanê heta Îlonê. Me konên reş vedidan, û her sibe pez didotin.", "Mayıstan eylüle kadar. Kara çadırlar kurardık ve her sabah koyunları sağardık.|From May until September. We put up black tents, and every morning we milked the sheep.|Von Mai bis September. Wir schlugen schwarze Zelte auf und molken jeden Morgen die Schafe."),
  ("Dapîr", "Min û jinên din, ji şîrê pez penîr û rûn çêdikirin. Kar pir bû, lê dilê me şa bû!", "Ben ve diğer kadınlar koyun sütünden peynir ve yağ yapardık. İş çoktu ama gönlümüz şendi!|The other women and I made cheese and butter from the sheep's milk. There was a lot of work, but our hearts were happy!|Ich und die anderen Frauen machten aus der Schafsmilch Käse und Butter. Es gab viel Arbeit, aber unsere Herzen waren froh!"),
  ("Juji", "Ma tiştek heye ku hûn niha bêriya wî dikin?", "Şimdi özlediğiniz bir şey var mı?|Is there something you miss now?|Gibt es etwas, das ihr jetzt vermisst?"),
  ("Dapîr", "Erê... Şevên zozanan! Em li dora agir rûdiniştin, dengbêjan stran digotin, zarokan jî guhdarî dikirin.", "Evet... Yayla geceleri! Ateşin etrafında otururduk, dengbêjler şarkı söylerdi, çocuklar da dinlerdi.|Yes... The nights on the summer pastures! We sat around the fire, the dengbêj sang, and the children listened.|Ja... Die Nächte auf den Sommerweiden! Wir saßen ums Feuer, die Dengbêj sangen, und die Kinder hörten zu."),
  ("Bapîr", "Lê niha, gelek gund vala bûne. Ciwan çûne bajaran, û kesek naçe zozanan.", "Ama şimdi pek çok köy boşaldı. Gençler şehirlere gitti, kimse yaylaya gitmiyor.|But now, many villages have emptied. The young have gone to the cities, and nobody goes to the pastures.|Aber jetzt sind viele Dörfer leer. Die Jungen sind in die Städte gezogen, und niemand geht mehr auf die Sommerweiden."),
  ("Juji", "Eger îro hûn ciwan bûna, hûn ê dîsa biçûna zozanan?", "Bugün genç olsaydınız yine yaylaya gider miydiniz?|If you were young today, would you go to the pastures again?|Wenn ihr heute jung wärt, würdet ihr wieder auf die Sommerweiden gehen?"),
  ("Bapîr", "Bê guman! Eger lingên min alîkariya min bikirana, ez ê sibê biçûma!", "Elbette! Bacaklarım bana yardım etseydi, yarın giderdim!|Of course! If my legs helped me, I would go tomorrow!|Natürlich! Wenn meine Beine mitmachten, würde ich morgen gehen!"),
  ("Dapîr", "Bapîr her tim wisa dibêje... lê ew ji xewa sibê jî pir hez dike!", "Dede hep böyle der... ama sabah uykusunu da çok sever!|Grandpa always says that... but he also loves his morning sleep!|Opa sagt das immer... aber er liebt auch seinen Morgenschlaf!"),
  ("Bapîr", "Ne rast e!... Belkî, hinekî rast e.", "Doğru değil! ... Belki biraz doğrudur.|That is not true! ... Maybe it is a little true.|Das stimmt nicht! ... Vielleicht stimmt es ein bisschen."),
  ("Juji", "Spas ji bo çîrokên we. Hevalno, hûn jî ji kal û pîrên xwe bipirsin: wan havîn çawa derbas dikirin? Heta podkasta din, xatirê we!", "Hikâyeleriniz için teşekkürler. Arkadaşlar, siz de büyüklerinize sorun: yazları nasıl geçirirlerdi? Bir sonraki podcaste kadar hoşça kalın!|Thanks for your stories. Friends, ask your grandparents too: how did they spend their summers? Until the next podcast, goodbye!|Danke für eure Geschichten. Freunde, fragt auch eure Großeltern: Wie haben sie ihre Sommer verbracht? Bis zum nächsten Podcast, tschüss!")],
 [["zozan", "yayla|summer pasture|Sommerweide"], ["kon", "çadır|tent|Zelt"], ["dotin", "sağmak|to milk|melken"], ["bêrî kirin", "özlemek|to miss|vermissen"], ["vala bûn", "boşalmak|to become empty|leer werden"], ["eger ... bûna", "...olsaydı|if ... were|wenn ... wäre"]],
 [{"q": "Yaylada ne kadar kalırlardı?|How long did they stay on the pastures?|Wie lange blieben sie auf den Sommerweiden?", "o": ["Mayıstan eylüle kadar|From May to September|Von Mai bis September", "Sadece bir hafta|Only one week|Nur eine Woche", "Bütün kış|All winter|Den ganzen Winter"], "a": 0},
  {"q": "Nine en çok neyi özlüyor?|What does Grandma miss most?|Was vermisst Oma am meisten?", "o": ["Yayla gecelerini|The nights on the pastures|Die Nächte auf den Sommerweiden", "Şehir hayatını|City life|Das Stadtleben", "Okulu|School|Die Schule"], "a": 0},
  {"q": "Dede neden şimdi gitmiyor?|Why doesn't Grandpa go now?|Warum geht Opa jetzt nicht?", "o": ["Bacakları yardım etmiyor|His legs won't help him|Seine Beine machen nicht mit", "Yaylayı sevmiyor|He doesn't like the pastures|Er mag die Sommerweiden nicht", "Çok meşgul|He is too busy|Er ist zu beschäftigt"], "a": 0}])

